def _run_syntax_check(p: Path) -> str:
    """Pythonファイルの構文チェックを実行する"""
    if p.suffix != ".py":
        return ""
    try:
        res = subprocess.run(
            ["python", "-m", "py_compile", str(p)],
            capture_output=True, text=True, timeout=5
        )
        if res.returncode == 0:
            return "\n✓ 構文チェック: OK"
        else:
            return f"\n⚠ 構文エラー検出:\n{res.stderr}"
    except Exception as e:
        return f"\n⚠ 構文チェック実行エラー: {e}"

def _generate_diff(old_text: str, new_text: str) -> str:
    """変更前後の差分を生成し、最大30行まで返す"""
    old_lines = old_text.splitlines(keepends=True)
    new_lines = new_text.splitlines(keepends=True)
    diff = list(difflib.unified_diff(old_lines, new_lines, n=3))
    
    if not diff:
        return ""
    
    if len(diff) > 30:
        # 行数を計算
        plus = sum(1 for l in diff if l.startswith('+') and not l.startswith('+++'))
        minus = sum(1 for l in diff if l.startswith('-') and not l.startswith('---'))
        diff_content = f"（差分が長いため省略。変更行数: +{plus}/-{minus}）"
    else:
        diff_content = "".join(diff).strip()
    
    return f"\n─── 差分 ───────────────────────────\n{diff_content}\n────────────────────────────────────"



class ExecutionRegistry:
    """
    スラッシュコマンドを登録・ルーティングするレジストリ。

    登録: @registry.register("name", "説明") デコレータ
    ルーティング: route("/name args") → (name, handler, args) または None

    handler のシグネチャ: fn(agent: GeminiAgent, args: str) -> None
    """

    def __init__(self):
        self._commands: dict[str, tuple[str, Any]] = {}  # name -> (description, handler)

    def register(self, name: str, description: str):
        def decorator(fn):
            self._commands[name.lower()] = (description, fn)
            return fn
        return decorator

    def route(self, text: str) -> Optional[tuple[str, Any, str]]:
        """
        スラッシュコマンドをパースしてハンドラを返す。
        Returns: (name, handler, remaining_args) or None
        """
        if not text.startswith("/"):
            return None
        parts = text[1:].split(maxsplit=1)
        key = parts[0].lower()
        args = parts[1] if len(parts) > 1 else ""
        if key in self._commands:
            _, handler = self._commands[key]
            return key, handler, args
        return None

    def help_text(self) -> str:
        lines = ["コマンド一覧:"]
        for name, (desc, _) in sorted(self._commands.items()):
            lines.append(f"  /{name:<20} - {desc}")
        lines.append("  exit                  - 終了")
        return "\n".join(lines)

