    """エージェントが使えるツールを管理"""

    def __init__(self):
        self._tools: dict[str, dict] = {}

    def register(self, name: str, description: str, parameters: dict):
        """ツールを登録"""
        def decorator(fn):
            self._tools[name] = {
                "fn": fn,
                "spec": {
                    "name": name,
                    "description": description,
                    "parameters": parameters,
                }
            }
            return fn
        return decorator

    def get_specs(self) -> list[dict]:
        return [v["spec"] for v in self._tools.values()]

    def copy_tool(self, name: str, source: "ToolRegistry") -> bool:
        """source レジストリからツール1件をコピーする。存在しない場合は False を返す。"""
        if name not in source._tools:
            return False
        self._tools[name] = source._tools[name]
        return True

    def execute(self, name: str, args: dict) -> Any:
        if name not in self._tools:
            raise ValueError(f"未知のツール: {name}")
        log.info({"tool_call": name, "args": args})
        return self._tools[name]["fn"](**args)

