@tools.register(
    name="get_repo_map",
    description=(
        "プロジェクトのディレクトリ構造とPythonファイルのクラス・関数構成をツリー状に取得する。"
        "不明なプロジェクト構造を把握するのに最適。"
    ),
    parameters={
        "type": "object",
        "properties": {
            "path": {"type": "string", "description": "構造を取得するルートディレクトリ（デフォルト: .）", "default": "."}
        }
    }
)
def get_repo_map(path: str = ".") -> str:
    import ast
    root = Path(path)
    if not root.exists():
        return f"エラー: ディレクトリが見つかりません: {path}"

    ignore_dirs = {".git", "__pycache__", "venv", "node_modules", ".idea", ".vscode"}
    output = [f"RepoMap: {root.resolve()}"]

    def _get_py_info(p: Path) -> str:
        try:
            content = _try_read_file_text(p)
            tree = ast.parse(content)
            defs = []
            for node in tree.body:
                if isinstance(node, ast.ClassDef):
                    methods = [n.name for n in node.body if isinstance(n, ast.FunctionDef)]
                    meth_str = f"({', '.join(methods)})" if methods else ""
                    defs.append(f"class {node.name}{meth_str}")
                elif isinstance(node, ast.FunctionDef):
                    defs.append(f"def {node.name}(...)")
            return " [" + ", ".join(defs[:10]) + (", ..." if len(defs) > 10 else "") + "]"
        except Exception:
            return ""

    for item in sorted(root.rglob("*")):
        if any(ignored in item.parts for ignored in ignore_dirs):
            continue
        rel = item.relative_to(root)
        depth = len(rel.parts)
        indent = "  " * (depth - 1)
        prefix = indent + ("└── " if depth > 0 else "")
        
        info = ""
        if item.is_file() and item.suffix == ".py":
            info = _get_py_info(item)
        
        line = f"{prefix}{item.name}{'/' if item.is_dir() else ''}{info}"
        output.append(line)
        
        if len("\n".join(output)) > 20000:
            output.append("... (出力制限のため省略)")
            break

    return "\n".join(output)

